/* @lc app=leetcode id=3629 lang=kotlin */ class Solution { companion object { val SPF: IntArray = IntArray(1000001) { it }.also { s -> (2..1000).forEach { i -> if (s[i] == i) (i * i..1000000 step i).forEach { j -> if (s[j] == j) s[j] = i } } } } fun minJumps(nums: IntArray): Int = nums.size.let { n -> SPF.let { spf -> HashMap<Int, ArrayList<Int>>().also { mult -> nums.indices.forEach { j -> generateSequence(nums[j]) { y -> (y / spf[y]).takeIf { it > 1 } }.takeWhile { it > 1 }.map { spf[it] }.distinct().forEach { q -> mult.getOrPut(q) { ArrayList() }.add(j) } } }.let { mult -> IntArray(n) { -1 }.also { it[0] = 0 }.let { dist -> HashSet<Int>().let { used -> generateSequence(listOf(0) to 0) { (f, lv) -> f.flatMap { i -> listOf(i + 1, i - 1).filter { it in 0 until n } + nums[i].let { p -> if (p >= 2 && spf[p] == p && used.add(p)) mult[p].orEmpty() else listOf() } }.filter { dist[it] == -1 }.distinct().onEach { dist[it] = lv + 1 }.takeIf { it.isNotEmpty() }?.let { it to lv + 1 } }.count().let { dist[n - 1] } } } } } } }